expected_spans.snippet:
available = stock["count"] - stock["reserved"]
if available < order["units"]:
    return {"state": "short", "units": available}

if scan["token"] in seen:
    continue
seen.add(scan["token"])

export function roomLimit(room: string): number {
    return room === "gallery" ? 40 : 12;
}

if (slot.room === wanted.room && wanted.start < slot.end && wanted.end > slot.start) {
    return "occupied";
}

let allowance = soil_allowance(soil);
if missing > allowance {
    return allowance;
}

pub fn soil_allowance(soil: &str) -> u32 {
    match soil { "clay" => 4, "sand" => 9, _ => 6 }
}

if kept.last().map_or(false, |last| position - last < gap) {
    continue;
}

let required = green.saturating_mul(2);
if brown < required {
    return Ok((0, required - brown));
}

if brown > required + 20 {
    return Ok(((brown - required) / 2, 0));
}

demand = seconds * lamp_cost(level)
if demand > battery:
    return {"state": "low", "used": 0}

mean = sum(usable) / len(usable)
if mean >= target:
    return "stop"

ratio = inner_width / inner_height
if ratio > 2:
    return {"shape": "panorama", "ratio": ratio}

title = item["title"].strip()
if not title:
    return "untitled"

export function stepSize(meter: string): number {
    return meter === "triplet" ? 1 / 3 : 1 / 4;
}

if (Math.round(beat / step) % 2 === 1) {
    beat += step * Math.max(0, Math.min(swing, 0.5));
}

if (left < 0 || right < 0) {
    throw new Error("negative cut");
}

if (total > ceiling) {
    const scale = ceiling / total;
    return positive.map(level => level * scale);
}

const length = end - start;
if (length <= 0) {
    return start;
}

if (position >= end) {
    return start + (position - start) % length;
}

pub fn slope_factor(surface: &str) -> u32 {
    match surface { "rock" => 3, "earth" => 2, _ => 1 }
}

if point.0 == i32::MIN || point.1 == i32::MIN {
    continue;
}

let delta = (point.0 - previous.0).abs() + (point.1 - previous.1).abs();
if delta > jump {
    break;
}

if clean.starts_with("山") {
    return format!("峰:{}", clean);
}

if distance >= 1000 {
    return format!("{} {}km", clean, distance / 1000);
}

let delta = (outgoing - incoming + 540).rem_euclid(360) - 180;
if delta.abs() < 15 {
    return "straight";
}
